require_once dirname(__DIR__).'/includes/functions.php';require_once dirname(__DIR__).'/includes/blockchain.php';require_role('admin');
 $chain=verify_chain(true);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if(in_array($status,['Open','Investigating','Resolved','False Alarm'],true))db()->prepare('UPDATE integrity_logs SET status=?,admin_notes=? WHERE id=?')->execute([$status,trim((string)($_POST['admin_notes']??'')),$id]);flash('success','Integrity case updated.');redirect('admin/integrity_failures.php');}
$ids=db()->query("SELECT DISTINCT registration_id FROM integrity_logs WHERE result='Tampered' AND registration_id IS NOT NULL UNION SELECT r.id FROM registrations r WHERE NOT EXISTS (SELECT 1 FROM blockchain_ledger l WHERE l.registration_id=r.id)")->fetchAll(PDO::FETCH_COLUMN);$issues=[];foreach($ids as $id){$v=verify_registration((int)$id,false);if(!$v['secure'])$issues[]=$v;}
$logs=db()->query("SELECT l.*,r.name,r.reg_no,e.title FROM integrity_logs l LEFT JOIN registrations r ON r.id=l.registration_id LEFT JOIN events e ON e.id=r.event_id WHERE l.result='Tampered' ORDER BY l.checked_at DESC LIMIT 100")->fetchAll();$pageTitle='Integrity failures';require dirname(__DIR__).'/includes/header.php';
?>
<div class="mb-4"><p class="text-danger text-uppercase small fw-bold mb-1">Investigate anomalies</p><h1 class="h2 fw-bold">Integrity failures</h1><p class="text-secondary">Detected mismatches and their field-level differences.</p></div>
<?php if(!$chain['healthy']):?><div class="alert alert-danger">Blockchain chain break detected at block(s): <?=e(implode(', ',$chain['breaks']))?>. Inspect the ledger monitor for link details.</div><?php endif;?>
<?php foreach($issues as $issue):$reg=$issue['registration'];?><div class="card p-4 mb-3 border-start border-4 border-danger"><div class="d-flex justify-content-between"><h2 class="h5"><?=e($reg['name'])?> · registration #<?=e((string)$reg['id'])?></h2><a href="<?=e(url('admin/verify.php?id='.(int)$reg['id']))?>">Verification report</a></div><p class="mb-1">Expected hash: <code><?=e((string)$issue['expected'])?></code></p><p class="mb-1">Current hash: <code><?=e((string)$issue['actual'])?></code></p><p class="mb-0">Changed fields: <strong><?=e($issue['fields']?implode(', ',$issue['fields']):'Ledger or chain link')?></strong></p></div><?php endforeach;?>
<h2 class="h5 fw-bold mt-4">Case history</h2><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>When</th><th>Student / event</th><th>Registration</th><th>Status / notes</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e(date('M j, H:i',strtotime($log['checked_at'])))?></td><td><?=e($log['name']??'Unknown')?> <div class="small text-secondary"><?=e($log['title']??'')?></div></td><td>#<?=e((string)$log['registration_id'])?></td><td><form method="post" class="d-flex gap-2"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$log['id']?>"><select class="form-select form-select-sm" name="status"><?php foreach(['Open','Investigating','Resolved','False Alarm'] as $st):?><option <?=$log['status']===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select><input class="form-control form-control-sm" name="admin_notes" value="<?=e($log['admin_notes'])?>" placeholder="Admin notes"><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="4" class="empty-state">No integrity failures have been recorded.</td></tr><?php endif;?></tbody></table></div>
